#[derive(Clone, PartialEq, ::prost::Message)]
pub struct RegisterRequest {
    /// Privacy: the client sends its login identifier here,
    /// hex(SHA-256("chatter/login-id/v1" || nickname)) = 64 chars, NOT a
    /// plaintext username (see LoginStartRequest.username).
    #[prost(string, tag="1")]
    pub username: ::prost::alloc::string::String,
    /// OPAQUE RegistrationRecord (192 bytes), finalized by the client against
    /// RequestRegistrationChallengeResponse.opaque_registration_response.
    #[prost(bytes="vec", tag="2")]
    pub opaque_registration_record: ::prost::alloc::vec::Vec<u8>,
    /// SVR (Secure Value Recovery) public key for PIN-based key recovery
    #[prost(bytes="vec", tag="3")]
    pub svr_public_key: ::prost::alloc::vec::Vec<u8>,
    /// PRIVACY: base64 of nonce(12) || AES-256-GCM(name padded to 53 or 257) ||
    /// tag(16) under the profile key. The server checks only that shape
    /// (internal/utils/validate/profile_ciphertext.go); max_len is the base64
    /// length of the largest bucket, MaxEncryptedDisplayNameLen.
    #[prost(string, tag="4")]
    pub display_name: ::prost::alloc::string::String,
    /// Device information for initial session
    #[prost(string, tag="6")]
    pub device_info: ::prost::alloc::string::String,
    #[prost(string, tag="7")]
    pub request_id: ::prost::alloc::string::String,
    /// Signal Protocol authentication (client-generated)
    /// If provided, server hashes device_auth_token and stores hash+salt
    ///
    /// Client-generated device auth token (Signal-style)
    #[prost(bytes="vec", tag="8")]
    pub device_auth_token: ::prost::alloc::vec::Vec<u8>,
    /// Registration lock token - prevents account takeover without PIN
    /// Derived client-side from PIN via SVR (HMAC-SHA256).
    /// Server stores hash; future re-registrations must present matching token.
    /// See Signal's RegistrationLock / AccountAttributes.registrationLock
    #[prost(bytes="vec", tag="9")]
    pub registration_lock: ::prost::alloc::vec::Vec<u8>,
    /// Signal Protocol prekey bundle (Signal-style: sent with registration)
    /// Contains identity key, registration_id, signed prekey, and Kyber prekey.
    /// This allows atomic registration + key upload like Signal does.
    /// The signed prekey signature IS the cryptographic proof of identity key possession.
    ///
    /// MANDATORY. An account registered without a bundle has no identity key on
    /// the server and no client-side path to ever publish one, so no peer can
    /// establish a session with it — permanently, silently unmessageable. The
    /// account is only useful if it is created together with its key material.
    #[prost(message, optional, tag="10")]
    pub prekey_bundle: ::core::option::Option<SignalPreKeyBundle>,
    /// Initial batch of one-time prekeys (Signal sends 100 at registration)
    #[prost(message, repeated, tag="11")]
    pub initial_one_time_prekeys: ::prost::alloc::vec::Vec<signal_pre_key_bundle::PreKeyRecord>,
    /// Registration challenge response - proves identity key possession
    /// Client signs the server-provided challenge nonce with identity private key
    #[prost(bytes="vec", tag="12")]
    pub challenge_response: ::prost::alloc::vec::Vec<u8>,
    /// RequestRegistrationChallengeResponse.challenge.token, echoed unchanged.
    /// The server checks it statelessly (it is bound to `username` and to the
    /// prekey bundle's identity key) and accepts it once.
    #[prost(bytes="vec", tag="13")]
    pub challenge_token: ::prost::alloc::vec::Vec<u8>,
    /// Discovery hash for Signal-style LookupUsername: libsignal's username
    /// hash of the full "nickname.discriminator" username
    /// (`usernames::Username::new(u)?.hash()`, a 32-byte compressed Ristretto255
    /// point). Computed only on the client; the server stores and matches it but
    /// never sees the username behind it. Independent of the login
    /// identifier carried in `username` above.
    #[prost(bytes="vec", tag="14")]
    pub username_lookup_hash: ::prost::alloc::vec::Vec<u8>,
    /// libsignal zero-knowledge proof that the caller knows the username behind
    /// username_lookup_hash (`usernames::Username::proof`). The server verifies it
    /// before storing the hash (as Signal-Server's AccountController does with
    /// Username.verifyProof), so a registrant cannot claim an arbitrary point
    /// or a hash they cannot open. 128 bytes: a poksho challenge scalar plus one
    /// response scalar for each of the statement's three secret scalars.
    #[prost(bytes="vec", tag="16")]
    pub username_proof: ::prost::alloc::vec::Vec<u8>,
    /// Unidentified Access Key (16 bytes), derived client-side from the profile
    /// key. Stored so the server can CHECK a sealed sender's presented key; it is
    /// never served back. After registration only SetUnidentifiedAccessKey moves it.
    #[prost(bytes="vec", tag="15")]
    pub unidentified_access_key: ::prost::alloc::vec::Vec<u8>,
    /// Proof of work for RequestRegistrationChallengeResponse.challenge: a
    /// solution for challenge_token as PowChallenge describes (Argon2id, domain
    /// "chatter-pow-v3/argon2id/register\0"). Ignored when the difficulty is 0.
    #[prost(fixed64, tag="17")]
    pub pow_solution: u64,
}
// ================== Registration Challenge ==================

/// RequestRegistrationChallengeRequest initiates the registration challenge flow.
/// The server generates a random nonce that the client must sign with their identity key.
#[derive(Clone, PartialEq, Eq, Hash, ::prost::Message)]
pub struct RequestRegistrationChallengeRequest {
    /// Privacy: the client sends its login identifier here,
    /// hex(SHA-256("chatter/login-id/v1" || nickname)) = 64 chars, NOT a
    /// plaintext username (see LoginStartRequest.username).
    #[prost(string, tag="1")]
    pub username: ::prost::alloc::string::String,
    /// Identity public key (Curve25519, 32 bytes). Bound into the challenge
    /// token; Register's prekey bundle must carry the same key.
    #[prost(bytes="vec", tag="2")]
    pub identity_public_key: ::prost::alloc::vec::Vec<u8>,
    /// OPAQUE RegistrationRequest (32 bytes). The server evaluates it under a
    /// fresh credential identifier (the challenge nonce), never under an
    /// existing account's, so this endpoint is no OPRF oracle on any password.
    #[prost(bytes="vec", tag="3")]
    pub opaque_registration_request: ::prost::alloc::vec::Vec<u8>,
}
/// RequestRegistrationChallengeResponse carries a stateless challenge: the
/// server stores nothing until a Register redeems it.
#[derive(Clone, PartialEq, Eq, Hash, ::prost::Message)]
pub struct RequestRegistrationChallengeResponse {
    /// Random 32-byte nonce the client signs with its identity private key
    /// (RegisterRequest.challenge_response, over
    /// "chatter-reg-challenge-v1\0" || challenge_nonce). It is the random part
    /// of challenge.token.
    #[prost(bytes="vec", tag="1")]
    pub challenge_nonce: ::prost::alloc::vec::Vec<u8>,
    /// Echo challenge.token as RegisterRequest.challenge_token and pay
    /// challenge.difficulty as RegisterRequest.pow_solution. Over the onion
    /// service the difficulty is never 0 and rises with sign-up load.
    #[prost(message, optional, tag="2")]
    pub challenge: ::core::option::Option<PowChallenge>,
    /// Challenge expires at (Unix timestamp nanoseconds)
    /// Client must complete registration before this time
    #[prost(fixed64, tag="3")]
    pub expires_at: u64,
    /// OPAQUE RegistrationResponse (64 bytes) for opaque_registration_request.
    #[prost(bytes="vec", tag="4")]
    pub opaque_registration_response: ::prost::alloc::vec::Vec<u8>,
}
