/// Event messages for auth service
#[derive(Clone, PartialEq, ::prost::Message)]
pub struct AuthEvent {
    /// Unix timestamp in nanoseconds
    #[prost(fixed64, tag="1")]
    pub timestamp: u64,
    /// Overall status update
    #[prost(enumeration="auth_event::RegistrationStatus", tag="2")]
    pub status: i32,
    #[prost(oneof="auth_event::Payload", tags="3, 4, 5")]
    pub payload: ::core::option::Option<auth_event::Payload>,
}
/// Nested message and enum types in `AuthEvent`.
pub mod auth_event {
    /// Represents the overall status of the registration workflow step
    #[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord, ::prost::Enumeration)]
    #[repr(i32)]
    pub enum RegistrationStatus {
        Unspecified = 0,
        /// Workflow initiated (Sent by gRPC handler)
        RegistrationStarted = 1,
        /// Account creation process underway
        AccountCreating = 2,
        /// Core account record exists (Sent after DB write)
        AccountCreated = 3,
        /// SpiceDB relationships created
        AuthzRelationsInitialized = 4,
        /// User profile created/updated
        UserProfileCreated = 5,
        /// Final setup & session creation (if applicable)
        LoggingIn = 6,
        /// Success! Session created (Includes Session payload)
        RegistrationCompleted = 7,
        /// Failure at any point (Includes Error payload)
        RegistrationFailed = 8,
    }
    impl RegistrationStatus {
        /// String value of the enum field names used in the ProtoBuf definition.
        ///
        /// The values are not transformed in any way and thus are considered stable
        /// (if the ProtoBuf definition does not change) and safe for programmatic use.
        pub fn as_str_name(&self) -> &'static str {
            match self {
                Self::Unspecified => "REGISTRATION_STATUS_UNSPECIFIED",
                Self::RegistrationStarted => "REGISTRATION_STARTED",
                Self::AccountCreating => "ACCOUNT_CREATING",
                Self::AccountCreated => "ACCOUNT_CREATED",
                Self::AuthzRelationsInitialized => "AUTHZ_RELATIONS_INITIALIZED",
                Self::UserProfileCreated => "USER_PROFILE_CREATED",
                Self::LoggingIn => "LOGGING_IN",
                Self::RegistrationCompleted => "REGISTRATION_COMPLETED",
                Self::RegistrationFailed => "REGISTRATION_FAILED",
            }
        }
        /// Creates an enum from field names used in the ProtoBuf definition.
        pub fn from_str_name(value: &str) -> ::core::option::Option<Self> {
            match value {
                "REGISTRATION_STATUS_UNSPECIFIED" => Some(Self::Unspecified),
                "REGISTRATION_STARTED" => Some(Self::RegistrationStarted),
                "ACCOUNT_CREATING" => Some(Self::AccountCreating),
                "ACCOUNT_CREATED" => Some(Self::AccountCreated),
                "AUTHZ_RELATIONS_INITIALIZED" => Some(Self::AuthzRelationsInitialized),
                "USER_PROFILE_CREATED" => Some(Self::UserProfileCreated),
                "LOGGING_IN" => Some(Self::LoggingIn),
                "REGISTRATION_COMPLETED" => Some(Self::RegistrationCompleted),
                "REGISTRATION_FAILED" => Some(Self::RegistrationFailed),
                _ => None,
            }
        }
    }
    #[derive(Clone, PartialEq, ::prost::Oneof)]
    pub enum Payload {
        /// Sent when status is ACCOUNT_CREATED
        #[prost(message, tag="3")]
        UserRegistered(super::User),
        /// Sent when status is REGISTRATION_COMPLETED
        #[prost(message, tag="4")]
        RegistrationComplete(super::RegistrationResult),
        /// Sent when status is REGISTRATION_FAILED
        #[prost(message, tag="5")]
        RegistrationError(super::Error),
    }
}
