#[derive(Clone, PartialEq, Eq, Hash, ::prost::Message)]
pub struct DeleteBackupRequest {
    /// HMAC-SHA256(svr_secret, "BackupId") — identifies which backup to delete
    #[prost(bytes="vec", tag="1")]
    pub backup_id_hash: ::prost::alloc::vec::Vec<u8>,
}
/// ChangePinBackupRequest atomically re-encrypts a backup with a new PIN-derived key.
///
/// Flow:
///    1. Client fetches old backup using old PIN
///    2. Client decrypts with old svr_secret
///    3. Client re-encrypts with new svr_secret
///    4. Client uploads new backup + new registration lock + new SVR public key
